using Microsoft.Data.Sqlite;
using System;
using System.Collections.Generic;

namespace VerimlilikUygulamasi
{
    public class BeslenmeGunlukVeri { public double Kalori { get; set; } public double Protein { get; set; } public double Karbonhidrat { get; set; } public double Yag { get; set; } }
    public class UykuGunlukVeri { public string UykuBaslangic { get; set; } public string UykuBitis { get; set; } public double ToplamSure { get; set; } }
    public class SuGunlukVeri { public double Litre { get; set; } }
    public class ElektrikGunlukVeri { public double Kwh { get; set; } public int KisiSayisi { get; set; } public int CihazSayisi { get; set; } }
    public class TelefonHaftalikVeri { public double ToplamDakika { get; set; } public double IsOkulDakika { get; set; } public double SosyalMedyaDakika { get; set; } }
    public class SporHaftalikVeri { public double YakilanKalori { get; set; } public double EgzersizSuresi { get; set; } public string AntrenmanTipi { get; set; } }

    public static class DatabaseHelper
    {
        private static readonly string DbFile = "verimlilik.db";
        private static readonly string ConnectionString = string.Format("Data Source={0}", DbFile);

        public static void InitializeDatabase()
        {
            using var connection = new SqliteConnection(ConnectionString);
            connection.Open();
            using var command = connection.CreateCommand();

            command.CommandText = @"
                CREATE TABLE IF NOT EXISTS Users (UserId INTEGER PRIMARY KEY AUTOINCREMENT, Gmail TEXT UNIQUE NOT NULL, KullAdi TEXT NOT NULL, Sifre TEXT NOT NULL, Kilogram REAL, BoyCm REAL, HareketDurumu TEXT, CreatedAt TEXT DEFAULT CURRENT_TIMESTAMP, UpdatedAt TEXT DEFAULT CURRENT_TIMESTAMP);
                CREATE TABLE IF NOT EXISTS BeslenmeVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, Kalori REAL, Protein REAL, Karbonhidrat REAL, Yag REAL, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS UykuVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, UykuBaslangic TEXT, UykuBitis TEXT, ToplamSure REAL, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikUykuSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS SuVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, Litre REAL, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikSuSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS ElektrikVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, Kwh REAL, KisiSayisi INTEGER DEFAULT 1, CihazSayisi INTEGER DEFAULT 0, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikElektrikSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS TelefonVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, ToplamDakika REAL, IsOkulDakika REAL, SosyalMedyaDakika REAL, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikTelefonSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS SporVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, YakilanKalori REAL, EgzersizSuresi REAL, AntrenmanTipi TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikSporSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS KardiyoVerileri (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Tarih TEXT, YakilanKalori REAL, EgzersizSuresi REAL, KardiyoTipi TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
                CREATE TABLE IF NOT EXISTS HaftalikKardiyoSeans (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, BaslangicZamani TEXT, FOREIGN KEY(UserId) REFERENCES Users(UserId));
            ";
            command.ExecuteNonQuery();

            command.CommandText = "INSERT OR IGNORE INTO Users (UserId, Gmail, KullAdi, Sifre) VALUES (1, 'test@verimlilik.com', 'Test', '1234');";
            command.ExecuteNonQuery();
        }

        public static bool KayitOl(string mail, string ad, string sifre) { try { using var conn = new SqliteConnection(ConnectionString); conn.Open(); var cmd = conn.CreateCommand(); cmd.CommandText = "INSERT INTO Users (Gmail, KullAdi, Sifre) VALUES (@mail, @ad, @sifre)"; cmd.Parameters.AddWithValue("@mail", mail); cmd.Parameters.AddWithValue("@ad", ad); cmd.Parameters.AddWithValue("@sifre", sifre); cmd.ExecuteNonQuery(); return true; } catch { return false; } }
        public static int GirisYap(string mail, string sifre) { using var conn = new SqliteConnection(ConnectionString); conn.Open(); var cmd = conn.CreateCommand(); cmd.CommandText = "SELECT UserId FROM Users WHERE Gmail = @mail AND Sifre = @sifre"; cmd.Parameters.AddWithValue("@mail", mail); cmd.Parameters.AddWithValue("@sifre", sifre); var res = cmd.ExecuteScalar(); return res != null ? Convert.ToInt32(res) : -1; }

        public static DateTime? GetActiveSessionStart(int userId) { using var connection = new SqliteConnection(ConnectionString); connection.Open(); var command = connection.CreateCommand(); command.CommandText = "SELECT BaslangicZamani FROM HaftalikSeans WHERE UserId = @userId ORDER BY Id DESC LIMIT 1"; command.Parameters.AddWithValue("@userId", userId); var result = command.ExecuteScalar(); if (result != null && result != DBNull.Value) { DateTime baslangic = DateTime.Parse(result.ToString()); if ((DateTime.Now - baslangic).TotalDays < 7) return baslangic; } return null; }
        public static void StartNewSession(int userId, DateTime baslangic) { using var connection = new SqliteConnection(ConnectionString); connection.Open(); var command = connection.CreateCommand(); command.CommandText = "INSERT INTO HaftalikSeans (UserId, BaslangicZamani) VALUES (@userId, @zaman)"; command.Parameters.AddWithValue("@userId", userId); command.Parameters.AddWithValue("@zaman", baslangic.ToString("yyyy-MM-dd HH:mm:ss")); command.ExecuteNonQuery(); }
        public static void SaveBeslenmeVerisi(int userId, DateTime tarih, double kalori, double protein, double karbonhidrat, double yag) { using var connection = new SqliteConnection(ConnectionString); connection.Open(); var command = connection.CreateCommand(); command.CommandText = "SELECT Id FROM BeslenmeVerileri WHERE UserId = @userId AND Tarih = @tarih"; command.Parameters.AddWithValue("@userId", userId); command.Parameters.AddWithValue("@tarih", tarih.ToString("yyyy-MM-dd")); var id = command.ExecuteScalar(); if (id != null) { command.CommandText = "UPDATE BeslenmeVerileri SET Kalori=@kalori, Protein=@protein, Karbonhidrat=@karbonhidrat, Yag=@yag WHERE Id=@id"; command.Parameters.AddWithValue("@id", (long)id); } else { command.CommandText = "INSERT INTO BeslenmeVerileri (UserId, Tarih, Kalori, Protein, Karbonhidrat, Yag) VALUES (@userId, @tarih, @kalori, @protein, @karbonhidrat, @yag)"; } command.Parameters.AddWithValue("@kalori", kalori); command.Parameters.AddWithValue("@protein", protein); command.Parameters.AddWithValue("@karbonhidrat", karbonhidrat); command.Parameters.AddWithValue("@yag", yag); command.ExecuteNonQuery(); }
        public static Dictionary<string, BeslenmeGunlukVeri> GetWeeklyRecords(int userId, DateTime haftaBaslangic) { var kayitlar = new Dictionary<string, BeslenmeGunlukVeri>(); using var connection = new SqliteConnection(ConnectionString); connection.Open(); var command = connection.CreateCommand(); command.CommandText = "SELECT Tarih, Kalori, Protein, Karbonhidrat, Yag FROM BeslenmeVerileri WHERE UserId = @userId AND Tarih BETWEEN @start AND @end"; command.Parameters.AddWithValue("@userId", userId); command.Parameters.AddWithValue("@start", haftaBaslangic.ToString("yyyy-MM-dd")); command.Parameters.AddWithValue("@end", haftaBaslangic.AddDays(6).ToString("yyyy-MM-dd")); using var reader = command.ExecuteReader(); while (reader.Read()) { kayitlar[reader.GetString(0)] = new BeslenmeGunlukVeri { Kalori = reader.GetDouble(1), Protein = reader.GetDouble(2), Karbonhidrat = reader.GetDouble(3), Yag = reader.GetDouble(4) }; } return kayitlar; }
