        public static Dictionary<string, SporHaftalikVeri> GetWeeklyKardiyoRecords(int userId, DateTime haftaBaslangic) { var kayitlar = new Dictionary<string, SporHaftalikVeri>(); using var connection = new SqliteConnection(ConnectionString); connection.Open(); var command = connection.CreateCommand(); command.CommandText = "SELECT Tarih, YakilanKalori, EgzersizSuresi, KardiyoTipi FROM KardiyoVerileri WHERE UserId = @userId AND Tarih BETWEEN @start AND @end"; command.Parameters.AddWithValue("@userId", userId); command.Parameters.AddWithValue("@start", haftaBaslangic.ToString("yyyy-MM-dd")); command.Parameters.AddWithValue("@end", haftaBaslangic.AddDays(6).ToString("yyyy-MM-dd")); using var reader = command.ExecuteReader(); while (reader.Read()) { kayitlar[reader.GetString(0)] = new SporHaftalikVeri { YakilanKalori = reader.GetDouble(1), EgzersizSuresi = reader.GetDouble(2), AntrenmanTipi = reader.IsDBNull(3) ? "Kardiyo" : reader.GetString(3) }; } return kayitlar; }
    }
